1	#!/usr/bin/env node
2	/**
3	 * Port of dataset/bech32/test14.py.
4	 *
5	 * Reads a comma separated list of integers plus three bit widths, regroups the
6	 * data from `--b` bit units into `--c` bit units, then again into `--d` bit
7	 * units, and prints both intermediate results.
8	 *
9	 *   node test14.mjs --a 165,53,183,4,81,215 --b 8 --c 5 --d 8
10	 *
11	 * The original is shipped as a frozen executable, so its `sys.argv[0]` -- and
12	 * therefore the program name argparse prints -- is `test14_executable`.
13	 */
14	
15	import { ArgumentParser } from './lib/argparse/parser.mjs';
16	import { intType, strType } from './lib/argparse/types.mjs';
17	import * as bech32 from './lib/bech32/index.mjs';
18	import { frame, inFrame } from './lib/python/errors.mjs';
19	import { pyPrint } from './lib/python/io.mjs';
20	import { pyInt } from './lib/python/pyint.mjs';
21	import { runFrozenScript } from './lib/python/runtime.mjs';
22	
23	const SCRIPT_FILE = 'test14.py';
24	const SCRIPT_STEM = 'test14';
25	const PROG = 'test14_executable';
26	
27	/**
28	 * Frames of the original script.  The column offsets are those of the failing
29	 * expression on each line, which is what the caret line marks:
30	 *   line 12: `data = list(map(int, args.a.split(',')))`
31	 *   line 13: `step1 = bech32.convertbits(data, args.b, args.c)`
32	 *   line 14: `step2 = bech32.convertbits(step1, args.c, args.d)`
33	 *   line 19: `main()`
34	 */
35	const FRAMES = {
36	  module: frame({ file: SCRIPT_FILE, line: 19, func: '<module>', colno: 4, endColno: 10 }),
37	  parseData: frame({ file: SCRIPT_FILE, line: 12, func: 'main', colno: 11, endColno: 44 }),
38	  step1: frame({ file: SCRIPT_FILE, line: 13, func: 'main', colno: 12, endColno: 52 }),
39	  step2: frame({ file: SCRIPT_FILE, line: 14, func: 'main', colno: 12, endColno: 53 }),
40	};
41	
42	function main() {
43	  const parser = new ArgumentParser({ prog: PROG });
44	  parser.add_argument('--a', { type: strType, required: true }); // Data as comma-separated integers
45	  parser.add_argument('--b', { type: intType, required: true }); // From bits
46	  parser.add_argument('--c', { type: intType, required: true }); // Intermediate bits
47	  parser.add_argument('--d', { type: intType, required: true }); // To bits
48	  const args = parser.parse_args(process.argv.slice(2));
49	
50	  const data = inFrame(FRAMES.parseData, () => args.a.split(',').map((piece) => pyInt(piece)));
51	  // Convert from bits to intermediate bits
52	  const step1 = inFrame(FRAMES.step1, () => bech32.convertbits(data, args.b, args.c));
53	  // Convert from intermediate to final bits
54	  const step2 = inFrame(FRAMES.step2, () => bech32.convertbits(step1, args.c, args.d));
55	  pyPrint(step1);
56	  pyPrint(step2);
57	}
58	
59	runFrozenScript({ scriptStem: SCRIPT_STEM, moduleFrame: FRAMES.module, main });
60

1	/**
2	 * `traceback.print_exception()` output.
3	 *
4	 * For every frame CPython prints the `File ...` line, then -- only when
5	 * `linecache` can actually find the source -- the stripped source line, then a
6	 * caret line marking the failing expression.  The carets come from the column
7	 * offsets recorded in the code object, mapped onto the line found on disk, and
8	 * are suppressed when the expression covers that whole line.
9	 */
10	
11	import { getLine } from './linecache.mjs';
12	import { isPySpace } from './unicodedata.mjs';
13	
14	const HEADER = 'Traceback (most recent call last):';
15	const SOURCE_INDENT = '    ';
16	
17	function isSpaceAt(text, index) {
18	  return isPySpace(text.codePointAt(index));
19	}
20	
21	/** `str.strip()`. */
22	function stripPython(text) {
23	  let start = 0;
24	  let end = text.length;
25	  while (start < end && isSpaceAt(text, start)) start += 1;
26	  while (end > start && isSpaceAt(text, end - 1)) end -= 1;
27	  return text.slice(start, end);
28	}
29	
30	/** Number of characters `str.lstrip()` would remove. */
31	function leadingWhitespace(text) {
32	  let count = 0;
33	  while (count < text.length && isSpaceAt(text, count)) count += 1;
34	  return count;
35	}
36	
37	const UTF8 = new TextEncoder();
38	
39	/**
40	 * `traceback._byte_offset_to_character_offset`: a UTF-8 byte offset mapped to a
41	 * character offset, clamped to the end of the line.
42	 */
43	function byteOffsetToCharacterOffset(line, byteOffset) {
44	  let bytes = 0;
45	  let characters = 0;
46	  for (const character of line) {
47	    if (bytes >= byteOffset) return characters;
48	    bytes += UTF8.encode(character).length;
49	    characters += character.length;
50	  }
51	  return characters;
52	}
53	
54	function formatFrame(frame) {
55	  const lines = [`  File "${frame.file}", line ${frame.line}, in ${frame.func}`];
56	  // The line is looked up on disk exactly as linecache does, so a run from a
57	  // directory without the sources prints the `File ...` line on its own.
58	  const rawLine = getLine(frame.file, frame.line);
59	  const sourceLine = stripPython(rawLine);
60	  if (sourceLine === '') return lines;
61	  lines.push(`${SOURCE_INDENT}${sourceLine}`);
62	
63	  if (frame.colno === null || frame.endColno === null) return lines;
64	  const stripped = leadingWhitespace(rawLine);
65	  const start = byteOffsetToCharacterOffset(rawLine, frame.colno) - stripped;
66	  const end = byteOffsetToCharacterOffset(rawLine, frame.endColno) - stripped;
67	  // Carets are shown only when they do not span the whole statement.
68	  if (end - start < sourceLine.length && end > start && start >= 0) {
69	    lines.push(`${SOURCE_INDENT}${' '.repeat(start)}${'^'.repeat(end - start)}`);
70	  }
71	  return lines;
72	}
73	
74	/**
75	 * @param {import('./errors.mjs').PyException} error
76	 * @returns {string} the traceback, newline terminated
77	 */
78	export function formatTraceback(error) {
79	  const lines = [HEADER];
80	  for (const frame of error.pyTraceback) lines.push(...formatFrame(frame));
81	  lines.push(error.exceptionLine);
82	  return `${lines.join('\n')}\n`;
83	}
